1	/**
2	 * Multi-agent SQL orchestration graph.
3	 *
4	 * Pipeline (LangGraph StateGraph over ChatbotState):
5	 *
6	 *   orch_plan  ─►  Send('orch_worker') × N  ─►  orch_synthesize
7	 *
8	 * - orch_plan       A planner agent reads the question plus a catalog of EVERY
9	 *                   schema/table in the database and decomposes it into 1..N
10	 *                   focused sub-tasks (or flags it as needing clarification).
11	 * - orch_worker     One SQL specialist agent per sub-task (LangGraph Send fan-out).
12	 *                   Each worker has its own message history and the full NBA SQL
13	 *                   toolset, and may query ANY schema/table in the database.
14	 * - orch_synthesize A synthesizer agent merges the workers' findings into one
15	 *                   grounded, natural-language answer.
16	 *
17	 * The graph writes the final answer as the last AI message on the shared
18	 * `messages` channel, so the existing streaming + eval layers consume it
19	 * unchanged.
20	 */
21	
22	import type { BaseMessage } from '@langchain/core/messages';
23	import { AIMessage, HumanMessage, SystemMessage, ToolMessage } from '@langchain/core/messages';
24	import type { StructuredTool } from '@langchain/core/tools';
25	import { END, MemorySaver, Overwrite, Send, START, StateGraph } from '@langchain/langgraph';
26	import { buildSystemPrompt } from '../systemPrompt.js';
27	import { captureError } from '../utils/errorCapture.js';
28	import { abortOptions, getAbortSignal } from './abort.js';
29	import { createModel } from './model.js';
30	import { buildSchemaCatalog } from './schemaCatalog.js';
31	import {
32	  ChatbotState,
33	  type ChatbotStateType,
34	  type ChatbotUpdateType,
35	  type Subtask,
36	  type WorkerFinding,
37	} from './state.js';
38	import { nbaTools } from './tools.js';
39	
40	const MAX_SUBTASKS = 4;
41	const MAX_WORKER_TOOL_ROUNDS = 6;
42	
43	const toolByName = new Map<string, StructuredTool>(nbaTools.map((t) => [t.name, t]));
44	
45	function messageContentToString(content: unknown): string {
46	  if (typeof content === 'string') return content;
47	  if (Array.isArray(content)) {
48	    return content
49	      .map((part) =>
50	        typeof part === 'string'
51	          ? part
52	          : part && typeof part === 'object' && 'text' in part
53	            ? String((part as { text?: unknown }).text ?? '')
54	            : '',
55	      )
56	      .join('');
57	  }
58	  return content == null ? '' : String(content);
59	}
60	
61	function lastHumanQuestion(messages: readonly BaseMessage[]): string {
62	  for (let i = messages.length - 1; i >= 0; i--) {
63	    const message = messages[i]!;
64	    if (message._getType() === 'human') {
65	      return messageContentToString(message.content).trim();
66	    }
67	  }
68	  // Fall back to the first message content if no explicit human turn is found.
69	  return messages.length > 0 ? messageContentToString(messages[0]!.content).trim() : '';
70	}
71	
72	// ---------------------------------------------------------------------------
73	// Planner agent
74	// ---------------------------------------------------------------------------
75	
76	function plannerPrompt(catalog: string): string {
77	  return [
78	    'You are the PLANNER in a multi-agent NBA analytics system. You do NOT write SQL.',
79	    'Your job is to decompose the user question into focused sub-tasks that independent',
80	    'SQL worker agents can answer in parallel, then return a JSON plan.',
81	    '',
82	    'You have access to EVERY schema and table in the database. The full catalog is below.',
83	    'Workers can query any of these schemas (main, nbadb, unified_star, stg_bref, api, audit,',
84	    'and all raw/staging schemas). Never assume a fact is unavailable just because it is not',
85	    'in the "main" schema.',
86	    '',
87	    'Rules:',
88	    '- Output ONLY a JSON object, no prose, no code fences.',
89	    '- Shape: {"mode": "single" | "multi" | "clarify", "subtasks": [{"id","focus","question"}]}.',
90	    '- "single": one self-contained lookup. Emit exactly one subtask whose question equals',
91	    '  (or lightly rephrases) the user question.',
92	    '- "multi": the question compares entities or has independent parts. Emit one subtask per',
93	    `  independent part (max ${MAX_SUBTASKS}). Example: "Who has more MVPs, LeBron or Kareem?"`,
94	    '  -> two subtasks, one per player.',
95	    '- "clarify": the question is genuinely ambiguous (e.g. "Who is the best player?",',
96	    '  "Tell me about the Lakers"). Emit "subtasks": [] and let the synthesizer ask.',
97	    '- Each subtask "question" must be fully self-contained (no pronouns referring to other',
98	    '  subtasks). "focus" is a 2-5 word label (e.g. "LeBron MVP count").',
99	    '- NORMALIZE ambiguous stat intent in the subtask wording:',
100	    '  - "Who led the NBA in [blocks/rebounds/assists/steals/points/three-pointers] in {season}?"',
101	    '    with NO "per game"/"average" -> rewrite to "Which player had the highest SEASON TOTAL',
102	    '    [stat] in {season} (sum of the per-season totals, regular season)?"',
103	    '  - Keep per-game phrasing only when the user explicitly says "per game" or "average".',
104	    '',
105	    'Database catalog (schema: tables):',
106	    catalog,
107	  ].join('\n');
108	}
109	
110	interface ParsedPlan {
111	  mode: 'single' | 'multi' | 'clarify';
112	  subtasks: Subtask[];
113	}
114	
115	function parsePlan(raw: string, question: string): ParsedPlan {
116	  const fallback: ParsedPlan = {
117	    mode: 'single',
118	    subtasks: [{ id: 't1', focus: 'primary lookup', question }],
119	  };
120	
121	  const start = raw.indexOf('{');
122	  const end = raw.lastIndexOf('}');
123	  if (start === -1 || end === -1 || end <= start) return fallback;
124	
125	  let parsed: unknown;
126	  try {
127	    parsed = JSON.parse(raw.slice(start, end + 1));
128	  } catch {
129	    return fallback;
130	  }
131	
132	  if (!parsed || typeof parsed !== 'object') return fallback;
133	  const obj = parsed as Record<string, unknown>;
134	  const mode = obj['mode'] === 'multi' || obj['mode'] === 'clarify' ? obj['mode'] : 'single';
135	
136	  if (mode === 'clarify') return { mode, subtasks: [] };
137	
138	  const rawSubtasks = Array.isArray(obj['subtasks']) ? obj['subtasks'] : [];
139	  const subtasks: Subtask[] = rawSubtasks
140	    .slice(0, MAX_SUBTASKS)
141	    .map((entry, index) => {
142	      const e = (entry ?? {}) as Record<string, unknown>;
143	      const q =
144	        typeof e['question'] === 'string' && e['question'].trim() ? e['question'].trim() : question;
145	      return {
146	        id: typeof e['id'] === 'string' && e['id'].trim() ? e['id'].trim() : `t${index + 1}`,
147	        focus: typeof e['focus'] === 'string' && e['focus'].trim() ? e['focus'].trim() : 'lookup',
148	        question: q,
149	      };
150	    })
151	    .filter((s) => s.question.length > 0);
152	
153	  if (subtasks.length === 0) return fallback;
154	  return { mode, subtasks };
155	}
156	
157	async function planNode(state: ChatbotStateType): Promise<ChatbotUpdateType> {
158	  const question = lastHumanQuestion(state.messages);
159	  const catalog = await buildSchemaCatalog();
160	  const workerBasePrompt = (await buildSystemPrompt()).trim();
161	
162	  let plan: ParsedPlan;
163	  try {
164	    const abortSignal = getAbortSignal();
165	    const response = await createModel().invoke(
166	      [new SystemMessage(plannerPrompt(catalog)), new HumanMessage(question)],
167	      abortSignal ? { signal: abortSignal } : {},
168	    );
169	    plan = parsePlan(messageContentToString(response.content), question);
170	  } catch (err) {
171	    captureError(err, { stage: 'orch_plan' });
172	    plan = { mode: 'single', subtasks: [{ id: 't1', focus: 'primary lookup', question }] };
173	  }
174	
175	  return {
176	    originalQuestion: question,
177	    planMode: plan.mode,
178	    subtasks: plan.subtasks,
179	    workerBasePrompt,
180	    workerFindings: new Overwrite([] as WorkerFinding[]),
181	  };
182	}
183	
184	// ---------------------------------------------------------------------------
185	// SQL worker agents (run in parallel)
186	// ---------------------------------------------------------------------------
187	
188	const WORKER_SUFFIX = `
189	You are a SQL WORKER agent in a multi-agent system. You were given ONE focused sub-task.
190	- You may query EVERY schema and table in the database, not just main. If a fact is not in
191	  main, look in nbadb, unified_star, stg_bref, api, audit, or the raw/staging schemas.
192	- Use the tools to discover schemas/columns and to run read-only SQL.
193	- Before writing SQL, do schema linking: name the ONE best table and the EXACT columns that
194	  answer the sub-task (use get_schema_info / find_stat_columns if unsure). Pick season TOTAL
195	  columns for "total"/"led the league" questions and per-game columns only when asked. Then
196	  write the smallest correct query. This planning is internal — do not narrate it in the final
197	  finding.
198	- Answer ONLY your sub-task. Be concise and factual. Report exact entities and exact numbers
199	  from the query results — never invent or round numbers.
200	- Name matching: player names may be stored WITH accents (e.g. "Nikola Jokić", "Luka Dončić").
201	  ALWAYS match names accent-insensitively using strip_accents on both sides, e.g.
202	  WHERE strip_accents(player_name) = strip_accents('Nikola Jokic'). If a plain = match on a name
203	  returns no rows, retry with strip_accents before concluding the data is absent.
204	- When you have enough evidence, stop calling tools and state your finding in one or two
205	  sentences, including the concrete value(s) you found.
206	- If the data is genuinely absent after checking the relevant schemas, say
207	  "Not available in the database." Do not guess.
208	`.trim();
209	
210	async function runWorker(subtask: Subtask, basePrompt: string): Promise<WorkerFinding> {
211	  const model = createModel().bindTools([...nbaTools]);
212	  const messages: BaseMessage[] = [
213	    new SystemMessage(
214	      `${basePrompt}\n\n${WORKER_SUFFIX}\n\nYour focused sub-task (${subtask.focus}): ${subtask.question}`,
215	    ),
216	    new HumanMessage(subtask.question),
217	  ];
218	
219	  let toolCalls = 0;
220	
221	  for (let round = 0; round < MAX_WORKER_TOOL_ROUNDS; round++) {
222	    const response = (await model.invoke(messages, abortOptions())) as AIMessage;
223	    messages.push(response);
224	
225	    const calls = response.tool_calls ?? [];
226	    if (calls.length === 0) {
227	      return {
228	        id: subtask.id,
229	        focus: subtask.focus,
230	        finding: messageContentToString(response.content).trim() || 'No finding produced.',
231	        toolCalls,
232	      };
233	    }
234	
235	    for (const call of calls) {
236	      toolCalls++;
237	      const tool = call.name ? toolByName.get(call.name) : undefined;
238	      let output: string;
239	      try {
240	        output = tool ? String(await tool.invoke(call.args)) : `Unknown tool "${call.name}".`;
241	      } catch (err) {
242	        captureError(err, { stage: 'orch_worker', toolName: call.name, intent: subtask.focus });
243	        output = `Tool error: ${err instanceof Error ? err.message : String(err)}`;
244	      }
245	      messages.push(
246	        new ToolMessage({
247	          content: output,
248	          tool_call_id: call.id ?? `${call.name}-${toolCalls}`,
249	          name: call.name,
250	        }),
251	      );
252	    }
253	  }
254	
255	  // Tool budget exhausted: force a tool-free summary of what was gathered.
256	  const summary = await createModel().invoke(
257	    [
258	      ...messages,
259	      new SystemMessage(
260	        'Tool budget reached. State your best factual finding now using ONLY the data already ' +
261	          'retrieved above. Do not request more tools.',
262	      ),
263	    ],
264	    abortOptions(),
265	  );
266	
267	  return {
268	    id: subtask.id,
269	    focus: subtask.focus,
270	    finding: messageContentToString(summary.content).trim() || 'No finding produced.',
271	    toolCalls,
272	  };
273	}
274	
275	async function workerNode(state: ChatbotStateType): Promise<ChatbotUpdateType> {
276	  const subtask = state.activeSubtask;
277	  if (!subtask) {
278	    return { workerFindings: [] };
279	  }
280	
281	  const basePrompt = state.workerBasePrompt ?? (await buildSystemPrompt()).trim();
282	  const finding = await runWorker(subtask, basePrompt);
283	  return { workerFindings: [finding] };
284	}
285	
286	function dispatchWorkers(state: ChatbotStateType): Send[] | 'orch_synthesize' {
287	  if (state.planMode === 'clarify' || !state.subtasks || state.subtasks.length === 0) {
288	    return 'orch_synthesize';
289	  }
290	  return state.subtasks.map((subtask) => new Send('orch_worker', { activeSubtask: subtask }));
291	}
292	
293	// ---------------------------------------------------------------------------
294	// Synthesizer agent
295	// ---------------------------------------------------------------------------
296	
297	const SYNTH_PROMPT = `
298	You are the SYNTHESIZER in a multi-agent NBA analytics system. You are given the user's
299	question and the findings of one or more SQL worker agents. Compose the final answer.
300	
301	Rules:
302	- Answer ONLY the user's question, in clear natural language. Never output raw SQL.
303	- Always name the subject explicitly (the player/team/season the question is about) rather than
304	  relying on pronouns, and include the key number/value the findings provide.
305	- Use ONLY facts and numbers present in the worker findings. Report numbers exactly as given;
306	  never invent, round, or estimate.
307	- For comparison questions, state the winner and both compared values.
308	- If the question was flagged as ambiguous (no findings provided), ask ONE concise
309	  clarification question instead of guessing.
310	- If the workers reported the data is missing/absent/not in the database, OR the question asks
311	  whether the database includes/contains something it does not, respond with EXACTLY this
312	  sentence: "I do not have that information in the database." Do not paraphrase it (avoid
313	  wording like "does not include").
314	- Emit exactly one final answer. Do not add follow-up offers.
315	`.trim();
316	
317	function buildSynthInput(state: ChatbotStateType): string {
318	  const question = state.originalQuestion ?? lastHumanQuestion(state.messages);
319	  if (state.planMode === 'clarify') {
320	    return `User question (flagged ambiguous — ask one clarifying question): ${question}`;
321	  }
322	  const findings = state.workerFindings ?? [];
323	  const findingLines =
324	    findings.length > 0
325	      ? findings.map((f) => `- [${f.focus}] ${f.finding}`).join('\n')
326	      : '- (no findings)';
327	  return `User question: ${question}\n\nWorker findings:\n${findingLines}`;
328	}
329	
330	async function synthesizeNode(state: ChatbotStateType): Promise<ChatbotUpdateType> {
331	  const response = await createModel().invoke(
332	    [new SystemMessage(SYNTH_PROMPT), new HumanMessage(buildSynthInput(state))],
333	    abortOptions(),
334	  );
335	  const text = messageContentToString(response.content).trim();
336	  return { messages: [new AIMessage(text)] };
337	}
338	
339	// ---------------------------------------------------------------------------
340	// Graph assembly
341	// ---------------------------------------------------------------------------
342	
343	function buildOrchestratorGraph() {
344	  return new StateGraph(ChatbotState)
345	    .addNode('orch_plan', planNode)
346	    .addNode('orch_worker', workerNode)
347	    .addNode('orch_synthesize', synthesizeNode)
348	    .addEdge(START, 'orch_plan')
349	    .addConditionalEdges('orch_plan', dispatchWorkers, ['orch_worker', 'orch_synthesize'])
350	    .addEdge('orch_worker', 'orch_synthesize')
351	    .addEdge('orch_synthesize', END)
352	    .compile({ checkpointer: new MemorySaver() });
353	}
354	
355	let _orchestrator: ReturnType<typeof buildOrchestratorGraph> | undefined;
356	
357	export function getOrchestratorGraph() {
358	  if (!_orchestrator) {
359	    _orchestrator = buildOrchestratorGraph();
360	  }
361	  return _orchestrator;
362	}
363	
364	export function resetOrchestratorGraph(): void {
365	  _orchestrator = undefined;
366	}
367	
368	// Exported for unit testing.
369	export { buildSynthInput, parsePlan, plannerPrompt, runWorker };
