(async () => {
  const r = await fetch('/api/chat-stream', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({messages:[{role:'user',content:'Who led the NBA in total points in the 2022-23 regular season?'}]}) });
  const reader = r.body.getReader(); const dec = new TextDecoder(); let buf=''; const types={}; let answer=''; let reasoning=''; const tools=[];
  while(true){ const {done,value}=await reader.read(); if(done) break; buf+=dec.decode(value,{stream:true}); const parts=buf.split('\n\n'); buf=parts.pop()||'';
    for(const p of parts){ const l=p.split('\n').find(x=>x.startsWith('data: ')); if(!l) continue; const e=JSON.parse(l.slice(6)); types[e.type]=(types[e.type]||0)+1;
      if(e.type==='token') answer+=e.content; if(e.type==='reasoning') reasoning+=e.content; if(e.type==='tool_start') tools.push({name:e.name, sql:e.sql?e.sql.slice(0,80):null}); if(e.type==='done') answer=e.content; } }
  return JSON.stringify({types, answer: answer.slice(0,300), reasoningLen: reasoning.length, reasoningSample: reasoning.slice(0,200), tools}, null, 2);
})()

